    const pax = paxMatch ? paxMatch[1] : null;
    const amt = parseFloat(amtMatch[1]);
    const currency = amtMatch[2];
    const flt = fltMatch ? fltMatch[1] : null;

    const amtUSD = currency === 'EUR' ? Math.round(amt * fxRate * 100) / 100 : amt;

    totalUSD += amtUSD;

    results.push({ ref, pax, flt, amtOrig: `${amt.toFixed(2)} ${currency}`, amtUSD: amtUSD.toFixed(2) });
}

return { fxRate, cancellations: results, totalUSD: Math.round(totalUSD * 100) / 100 };

