const raw = readFile(input.file);
const lines = raw.split('\n');

// Find fx rate
let fxRate = null;
for (const line of lines) {
  const m = line.match(/## fx: 1 EUR = ([\d.]+) USD/);
  if (m) { fxRate = parseFloat(m[1]); break; }
}

const cancellations = [];

for (const line of lines) {
  if (!/^\[.*\]\s+CXL\s/.test(line)) continue;

  // Extract fields — they can be in any order
  const refMatch = line.match(/ref=(\S+)/);
  const paxMatch = line.match(/pax="([^"]+)"/);
  const fltMatch = line.match(/flt=(\S+)/);
  const amtMatch = line.match(/amt=([\d.]+)(USD|EUR)/);

  if (!refMatch || !paxMatch || !fltMatch || !amtMatch) continue;

  const ref = refMatch[1];
  const pax = paxMatch[1];
  const flt = fltMatch[1];
  const amtVal = parseFloat(amtMatch[1]);
  const amtCur = amtMatch[2];

  let usdAmt = amtCur === 'USD' ? amtVal : amtVal * fxRate;
  usdAmt = Math.round(usdAmt * 100) / 100;

  cancellations.push({
    ref,
    pax,
    flt,
    origAmt: `${amtVal.toFixed(2)} ${amtCur}`,
    usdAmt
  });
}

const total = cancellations.reduce((s, c) => s + c.usdAmt, 0);

return {
  fxRate,
  cancellations,
  totalUsd: Math.round(total * 100) / 100,
  count: cancellations.length
};

